import {orderOverviewMarkup} from './overview.js?v=ui-batch234-20261027';
import {costCompositionMarkup} from './cost-composition.js?v=batch2-payments-20261023';
import {createPaymentEntry} from './payment-entry.js?v=batch2-payments-20261023';
import {websiteDossierSlot} from '../analytics/dossier.js?v=inquiry-headers-20261023';
import {orderHeaderMarkup,revealOrderTab} from './header.js?v=ui-batch3-followup-20261027';
import {moneyBasisBadge} from '../workspace/money.js?v=money-basis-20261021';
import {createDirectPurchase} from './direct-purchase.js?v=ui-batch234-20261027';
import {orderExecutionMarkup} from './progress.js?v=ui-batch234-20261027';
import {executionStages,orderExecution} from '../../shared/order-progress.js?v=ui-batch234-20261027';
import {displayOrderStage} from '../../shared/companies.js';
import {salesFunnel} from '../../shared/sales-funnel.js?v=ui-batch234-20261027';
import {installCostingBasisNotice} from './materials.js';
import {vatReasonFields,installVatReasonFields,updateVatReasonFields,readVatReasonFields} from './vat-reason.js';
