function readItems(){return [...context.$('#items').children].map(el=>{const get=k=>el.querySelector(`[name=${k}]`).value,unknown=el.querySelector('[name=measurementUnknown]').checked;const previous=context.state.orders.flatMap(o=>o.items).find(i=>i.id===el.dataset.itemId);const item={...previous,id:el.dataset.itemId||context.uid(),cost:el.querySelector('[name=cost]')?(get('cost')===''?null:context.cents(get('cost'))):el.dataset.cost===undefined?null:Number(el.dataset.cost),description:get('description').trim(),quantity:Number(get('quantity')),width:unknown?null:Number(get('width')),height:unknown?null:Number(get('height')),price:get('price')===''?null:context.cents(get('price')),printColors:el.querySelector('[name=printColors]')?(get('printColors')===''?null:Number(get('printColors'))):previous?.printColors??null,...(context.company.tool==='costing'?{material:get('material').trim(),thickness:get('thickness')===''?null:Number(get('thickness'))}:{}),specs:get('specs').trim(),productionSource:get('productionSource')};const invalidItemField=!item.description?'description':!Number.isInteger(item.quantity)||item.quantity<1?'quantity':!unknown&&(!Number.isInteger(item.width)||item.width<1)?'width':!unknown&&(!Number.isInteger(item.height)||item.height<1)?'height':item.price!=null&&(!Number.isSafeInteger(item.price)||item.price<0)?'price':item.cost!=null&&(!Number.isSafeInteger(item.cost)||item.cost<0)?'cost':context.company.tool==='costing'&&item.material.length>200?'material':context.company.tool==='costing'&&item.thickness!=null&&(!Number.isFinite(item.thickness)||item.thickness<=0||item.thickness>1000000)?'thickness':context.company.tool==='design'&&item.printColors!=null&&(!Number.isInteger(item.printColors)||item.printColors<0||item.printColors>99)?'printColors':null;if(invalidItemField)throw context.formProblem('Controleer dit productveld.',{field:el.querySelector('[name='+invalidItemField+']')});const pickedBasis=context.company.tool==='costing'?context.readCostingLink(el)?.linkedFields:null;if(item.costSource==='calculator'&&previous&&!sameCostingFields(item,pickedBasis,[...costingBasisFields,'cost'])&&!sameCostingFields(item,previous,[...costingBasisFields,'cost'])){if(item.cost===previous.cost)item.cost=null;delete item.costSource;delete item.calculatedCostTotal;}if(item.costSource==='supplierInvoice'){const invoiced=context.state.purchases.flatMap(p=>context.supplierInvoices(p).flatMap(inv=>(inv.lines||[]).filter(l=>l.itemId===item.id)));item.purchaseCostQuantity=invoiced.reduce((sum,l)=>sum+context.physicalQuantity(l),0);item.purchaseCostTotal=invoiced.reduce((sum,l)=>sum+l.quantity*l.price,0);if(item.productionSource==='local'&&invoiced.length)throw context.formProblem('Dit product is gekoppeld aan een leveranciersfactuur. Pas eerst die inkoopregel aan voordat je lokale productie kiest.',{field:el.querySelector('[name=productionSource]')});if(item.quantity<item.purchaseCostQuantity)throw context.formProblem('Er zijn meer stuks op leveranciersdocumenten gekoppeld dan dit nieuwe aantal. Pas eerst die inkoopregels aan.',{field:el.querySelector('[name=quantity]')});if(item.quantity!==item.purchaseCostQuantity)item.cost=null;}if(context.company.id==='spatlappen')Object.assign(item,context.readExecutionFields(el));context.formRecordProvenance(el,item);return context.company.tool==='costing'?context.finishCostingItem(item,el):item;});}

