function orderTimeline(o){
 const p=context.purchase(o.purchaseId),plastic=context.company.tool==='costing';
 const entries=plastic?[['Aanvraag ontvangen','date','Nieuwe aanvraag'],['Offerte verstuurd','quoteSentDate','Offerte verstuurd'],['Wachten op betaling','paymentRequestedDate','Wachten op betaling'],['Besteld bij leverancier','supplierOrderedDate','Besteld bij leverancier'],['In uitvoering','productionDate','In productie'],['Onderweg','transitDate','Onderweg naar Nederland'],['Binnengekomen','arrivedDate','Binnen in Nederland'],['Verzonden','shippedDate','Verzonden'],['Afgerond','deliveredDate','Afgerond']]:[['Ontwerp maken','date'],['Wachten op goedkeuring','designSentDate'],['Ontwerp goedgekeurd','approvedDate'],['Offerte verstuurd','quoteSentDate'],['Wachten op betaling','paymentRequestedDate'],['Productie vrijgegeven','productionReleasedDate'],['Besteld bij leverancier','supplierOrderedDate'],['In productie','productionDate'],['Onderweg naar Nederland','transitDate'],['Binnen in Nederland','arrivedDate'],['Verzonden','shippedDate'],['Afgerond','deliveredDate']];
 const index=entries.findIndex(([name,,stage])=>(stage||name)===displayOrderStage(o.stage,context.company.id));
 return `<ol class="timeline">${entries.map(([name,key],step)=>{const value=o[key]||(key==='supplierOrderedDate'?p?.orderedDate:key==='arrivedDate'?p?.arrivedDate:'');const current=step===index,passed=step<index;return `<li class="${value||passed?'done':''} ${current?'current':''}"><strong>${name}${current?' · nu':''}</strong><span>${value?context.date(value):current?'Huidige stap':passed?'Gepasseerd · datum onbekend':'Nog te doen'}</span></li>`;}).join('')}</ol>`;
}

function changeOrderStage(o,stage){if(stage===o.stage)return;o.stage=stage;o.statusHistory??=[];o.statusHistory.push({stage,date:context.today(),time:new Date().toISOString()});const key={'Wachten op goedkeuring':'designSentDate','Ontwerp goedgekeurd':'approvedDate','Offerte verstuurd':'quoteSentDate','Wachten op betaling':'paymentRequestedDate','Productie vrijgegeven':'productionReleasedDate','Besteld bij leverancier':'supplierOrderedDate','In productie':'productionDate','Onderweg naar Nederland':'transitDate','Binnen in Nederland':'arrivedDate','Verzonden':'shippedDate','Afgerond':'deliveredDate'}[stage];if(key&&!o[key])o[key]=context.today();}

function registerOrderProgress(o,stage='',quoteOnly=false){
 if(!o)throw Error('Deze order bestaat niet meer.');
 if(stage&&!context.stages.includes(stage))throw Error('Deze status hoort niet bij dit bedrijf. Herlaad de pagina en gebruik Voortgang bijwerken.');
 const expected=JSON.stringify(o),keys={'Wachten op goedkeuring':'designSentDate','Ontwerp goedgekeurd':'approvedDate','Offerte verstuurd':'quoteSentDate','Wachten op betaling':'paymentRequestedDate','Productie vrijgegeven':'productionReleasedDate','Besteld bij leverancier':'supplierOrderedDate','In productie':'productionDate','Onderweg naar Nederland':'transitDate','Binnen in Nederland':'arrivedDate','Verzonden':'shippedDate','Afgerond':'deliveredDate'};
 const initial=stage||orderExecution(o).stage||(['Wachten op goedkeuring','Ontwerp goedgekeurd'].includes(o.stage)?o.stage:''),localOnly=o.items.length>0&&o.items.every(item=>item.productionSource==='local'),choices=[...(context.company.tool==='design'?['Wachten op goedkeuring','Ontwerp goedgekeurd']:[]),...executionStages].filter(value=>!localOnly||!['Besteld bij leverancier','Onderweg naar Nederland','Binnen in Nederland'].includes(value)||value===initial);
 context.openForm('Voortgang van deze order',`<p>Deze registratie geldt voor order #${context.esc(o.sourceNumber||o.number)}. Een gezamenlijke inkoopbestelling is hiervoor niet nodig.</p>${stage?'<p><strong>'+context.esc(stage)+'</strong></p>':'<label>Wat is er gebeurd?<select name="progressStage" required><option value="">Kies een gebeurtenis</option>'+choices.map(value=>'<option value="'+context.esc(value)+'" '+(initial===value?'selected':'')+'>'+context.esc(value)+'</option>').join('')+'</select></label>'}${context.field('eventDate','Datum waarop dit is gebeurd',o[keys[initial]]||context.today(),'date','required')}<label class="check-row form-spaced"><input name="dateUnknown" type="checkbox">Datum nog onbekend</label><label class="check-row"><input name="confirmProgress" type="checkbox" required>Ik bevestig dat dit met deze order is gebeurd. Afgerond verplaatst het dossier naar het archief.</label><p class="form-help">Betalingen en verzonden documenten blijven hun eigen registraties houden. Andere orders en de gezamenlijke inkoopbestelling worden niet aangepast.</p>`,async fd=>{
  const selected=stage||String(fd.get('progressStage')||''),key=keys[selected],eventDate=fd.has('dateUnknown')?'':String(fd.get('eventDate')||'');
  if(!context.stages.includes(selected)||!stage&&!choices.includes(selected))throw context.formProblem('Kies een geldige gebeurtenis voor deze order.',{field:'progressStage'});
  if(!fd.has('confirmProgress'))throw context.formProblem('Bevestig eerst dat dit is gebeurd.',{field:'confirmProgress'});
  if(!fd.has('dateUnknown')&&(!/^\d{4}-\d{2}-\d{2}$/.test(eventDate)||!Number.isFinite(Date.parse(eventDate))||new Date(eventDate+'T12:00:00Z').toISOString().slice(0,10)!==eventDate))throw context.formProblem('Vul een geldige datum in of kies Datum nog onbekend.',{field:'eventDate'});
  await context.mergeStoredState(next=>{const updated=next.orders.find(x=>x.id===o.id);if(!updated||JSON.stringify(updated)!==expected)throw Error('Deze order is intussen gewijzigd. Je invoer blijft staan; open de voortgang opnieuw.');
   if(selected==='Ontwerp goedgekeurd'&&updated.items.some(item=>item.designVariants?.length)&&!orderDesignApproved(next,updated))throw Error('Kies eerst bij elk product het definitieve ontwerp. De algemene orderstatus kan die keuze niet vervangen.');
   if(!quoteOnly||context.stages.indexOf(updated.stage)<=context.stages.indexOf(selected))changeOrderStage(updated,selected);
   if(key)updated[key]=eventDate;if(selected==='Afgerond')updated.archived=true;
   next.activities.unshift({id:context.uid(),message:`Order #${updated.sourceNumber||updated.number}: ${selected} geregistreerd`,time:new Date().toISOString()});
  });
 },{afterSave:()=>{context.render();context.toast('Voortgang van deze order bijgewerkt');}});
 const form=context.$('#dialog form');form.querySelector('[type=submit]').textContent='Voortgang opslaan';
 form.elements.progressStage?.addEventListener('change',()=>{form.elements.dateUnknown.checked=false;form.elements.eventDate.disabled=false;form.elements.eventDate.required=true;form.elements.eventDate.value=o[keys[form.elements.progressStage.value]]||context.today();});
}

function workflowActions(o){
 if(context.company.id==='maatwerkkunststof'){const f=salesFunnel(context.state,o,context.company.id);return `<div class="workflow-bar"><p>${context.esc(f.label)}</p><button type="button" data-funnel-action="${context.esc(f.next[0])}" data-id="${context.esc(o.id)}">${context.esc(f.next[1])}</button></div>`;}
 const automatic=salesFunnel(context.state,o,context.company.id);if(automatic.automaticRelease||automatic.paymentPrepared&&automatic.phase==='confirmation')return `<div class="workflow-bar"><p>${context.esc(automatic.label)}${automatic.paymentPrepared&&!automatic.automaticRelease?' · bevestiging en betaallink gereed':''}</p><button type="button" data-funnel-action="${context.esc(automatic.next[0])}" data-id="${context.esc(o.id)}">${context.esc(automatic.next[1])}</button></div>`;
 const t=context.totals(o);let action='',label='',help='';
 switch(o.stage){
 case 'Ontwerp maken': action='design-ready';label='Verzending ontwerp registreren';help='Maak het voorbeeld en stuur het aan de klant.';break;
 case 'Wachten op goedkeuring': action='approve-design';label='Ontwerpgoedkeuring registreren';help='Wacht op akkoord van de klant voordat je de offerte maakt.';break;
 case 'Ontwerp goedgekeurd': action=o.quoteDraft?'quote-sent':'quote';label=o.quoteDraft?'Verzending offerte registreren':'Offerte maken';help=o.quoteDraft?'Je offerte staat klaar. Registreer verzending nadat je hem zelf hebt verstuurd.':'Het ontwerp is goedgekeurd. Maak nu het prijsvoorstel.';break;
 case 'Offerte verstuurd': action=t.paid>0?'link-purchase':'request-payment';label=t.paid>0?'Inkoopbestelling kiezen':'Betaalverzoek registreren';help=t.paid>0?'Er is al geld ontvangen. Kies de gezamenlijke inkoopbestelling.':'De offerte is verstuurd. Registreer hierna de ontvangen betaling.';break;
 case 'Wachten op betaling': action=t.paid>0?'link-purchase':'payment';label=t.paid>0?'Inkoopbestelling kiezen':'Betaling registreren';help=t.paid>0?`${context.euro(t.paid)} ontvangen. Je kunt na de afgesproken aanbetaling inkopen.`:'Registreer geld zodra je het daadwerkelijk hebt ontvangen.';break;
 case 'Productie vrijgegeven': action='link-purchase';label='Inkoopbestelling koppelen';help='Productie is vrijgegeven. Registreer bestellen en productiestart zodra die bevestigd zijn.';break;
 case 'Besteld bij leverancier': action='set-production';label='Productiestart registreren';help='Werk de voortgang bij zodra de leverancier begint.';break;
 case 'In productie': action='set-transit';label='Vertrek leverancier registreren';help='Werk de voortgang bij zodra de bestelling vertrekt.';break;
 case 'Onderweg naar Nederland': action='set-arrived';label='Aankomst registreren';help='Registreer wanneer de bestelling in Nederland binnen is.';break;
 case 'Binnen in Nederland': action='set-shipped';label='Verzending naar klant registreren';help='Controleer het resterende saldo en regel de levering.';break;
 case 'Verzonden': action='set-completed';label='Ontvangst klant registreren';help='Rond af zodra de klant de bestelling heeft ontvangen.';break;
 case 'Afgerond': help='Deze order is afgerond. Je kunt betalingen en documenten blijven bekijken.';break;
 }
 const p=context.purchase(o.purchaseId);if(action==='link-purchase'&&!p&&context.company.id==='maatwerkkunststof'){action='costs';label='Inkoop bij leverancier invullen';help='Leg de leverancier en kosten direct bij deze order vast. Een gezamenlijke inkoopbestelling is optioneel.';}if(action==='link-purchase'&&p){action='order-supplier-status';label='Bestellen bij leverancier registreren';help=`Gekoppeld aan ${p.name}. Registreer wanneer je de bestelling daadwerkelijk hebt geplaatst.`;}
 const mixed=o.items.some(i=>i.productionSource==='local')&&context.supplierItems(o).length>0;
 return `<div class="workflow-bar"><div><p>${context.esc(help)}</p></div>${action?context.button(action,label,o.id,true):context.badge('Afgerond','green')}</div>${mixed&&o.stage!=='Afgerond'?'<p class="notice">Deze order heeft twee productieroutes: leverancier en lokaal in Nederland. Transport naar Nederland geldt voor het leveranciersdeel. Controleer vóór verzending naar de klant of beide delen klaar zijn.</p>':''}`;
}

function selectOrderTab(tab){const id=context.route()[1];context.orderView={id,tab};history.replaceState(null,'',`#orders/${id}/${tab}`);renderOrder(id);}
return {packagePriceFields,readPackagePrice,updatePackagePricing,renderOrder,orderCostsView,orderPaymentsView,costForm,itemDimensions,productionLabel,updateItemMeasurements,installOrderCosting,itemFields,readItems,updateCombinedOrderForm,orderForm,paymentForm,noteForm,quoteForm,orderTimeline,changeOrderStage,registerOrderProgress,workflowActions,selectOrderTab};
